import json,re,hashlib
from pathlib import Path
from html.parser import HTMLParser
from xml.etree import ElementTree as ET

class Text(HTMLParser):
 def __init__(self): super().__init__(convert_charrefs=True); self.parts=[]
 def handle_data(self,data): self.parts.append(data)
def plain(xml):
 p=Text(); p.feed(xml); return ''.join(p.parts).strip()

src=json.loads(Path('source.json').read_text()); ans=json.loads(Path('answer.json').read_text())
assert len(src)==len(ans)==3
required={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status','substantive_impact'}
classes={'material_reduction','coordination_only','retained_necessary','financing_transfer','payment_timing_relief','mixed','reserved','editorial_only'}
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
for s,a in zip(src,ans):
 assert required<=set(a)
 for key in ['code_id','source_id','source_sha256','number']: assert a[key]==s[key],key
 print('\\n### RELECTURE',s['number'])
 print('SOURCE INTÉGRALE :',s['source_xml'])
 print('NOTES SOURCE :',repr(s['source_notes_xml']))
 if a['status']=='retained_unchanged':
  assert a['proposed_xml'] is None
  assert a['classification']=='retained_necessary'
  assert a['substantive_impact']['effects']==[]
  print('PROPOSITION : maintien intégral, par reprise de la source ci-dessus ; proposed_xml=null.')
 else:
  print('PROPOSITION INTÉGRALE :',a['proposed_xml'])
  doc=ET.fromstring('<root>'+a['proposed_xml']+'</root>')
  for n in doc.iter():
   if n.tag=='root': continue
   assert n.tag in allowed
   for k,v in n.attrib.items(): assert k in ['rowspan','colspan'] and v.isdigit()
  if a.get('change_type')=='full_repeal':
   assert plain(a['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé'))
   assert a['repeal_policy_id']=='editorial_direction_2026_10_19'
   assert len(a['repeal_scope'])>=30
 impact=a['substantive_impact']
 assert impact['version']==1 and impact['classification'] in classes
 for f in ['assessment','scope_limitations','new_burdens_review']: assert len(impact[f])>=40
 for effect in impact['effects']:
  assert effect['kind'] in kinds and effect['unit'] in units
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',effect['measure_id']) and 6<=len(effect['measure_id'])<=96
  assert set(effect)=={'kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote'}
  assert len(effect['source_quote'])>=12 and effect['source_quote'] in plain(s['source_xml'])
  assert len(effect['proposed_quote'])>=12 and effect['proposed_quote'] in plain(a['proposed_xml'])
 assert len(a.get('benefit_review',''))>=100
 if s.get('benefit_check_required'): assert 'benefit_review' in a
 print('STATUT :',a['status'],'; IMPACT :',impact['classification'],'; EFFETS :',len(impact['effects']))
print('\\nContrôles réussis : 3 objets, identifiants exacts, statuts, XML, transitions et citations avant/après conformes aux contraintes de format.')
PY"

